//
// Thus I'll craft the task around that. I'll define the function `maximumHappiness` that takes two vectors and returns the maximum sum under the constraint that no two selected values come from the same row and adjacent columns (i.e., you cannot select `row1[i]` and `row1[i+1]` both; similarly for `row2`). Equivalent: you cannot select two values from the same row if their column indices differ by 1.
//
// Edge cases: n=0 (should return 0, but we assume n>=1), negative values (though problem says non-negative, but we can handle), large values (use long long). DP states: `dp0` = max up to current column where we do NOT pick the top value at this column (i.e., we either pick bottom or skip). `dp1` = max up to current column where we do NOT pick the bottom value. Or better, define `takeTop` and `takeBottom` and `skip` separately. I'll use a clear DP: Let `best[i][0]` = max happiness up to column i (0-indexed) where we take the top score at column i. `best[i][1]` = max where we take bottom. `best[i][2]` = max where we take none. Then transitions: `best[i][0] = row1[i] + max(best[i-1][1], best[i-1][2])` because previous column cannot be top. `best[i][1] = row2[i] + max(best[i-1][0], best[i-1][2])`. `best[i][2] = max(best[i-1][0], best[i-1][1], best[i-1][2])`. Answer = max over the three at last column. Simplify by noting we only need last row's three values. Time O(n), space O(1).

#include <vector>
#include <algorithm>

// Returns the maximum total happiness under the constraint that
// you cannot pick two values from the same row if their column indices are adjacent.
long long maximumHappiness(int n, const std::vector<long long>& row1, const std::vector<long long>& row2) {
    if (n == 0) return 0;

    // dp0: max up to previous column when taking top at that column
    // dp1: max up to previous column when taking bottom at that column
    // dp2: max up to previous column when taking none
    long long dp0 = row1[0];
    long long dp1 = row2[0];
    long long dp2 = 0;

    for (int i = 1; i < n; ++i) {
        long long new0 = row1[i] + std::max(dp1, dp2);
        long long new1 = row2[i] + std::max(dp0, dp2);
        long long new2 = std::max({dp0, dp1, dp2});

        dp0 = new0;
        dp1 = new1;
        dp2 = new2;
    }

    return std::max({dp0, dp1, dp2});
}

#include <cassert>
#include <vector>

long long maximumHappiness(int n, const std::vector<long long>& row1, const std::vector<long long>& row2);

int main() {
    // Basic case: choose the larger of each column, no conflict
    assert(maximumHappiness(2, {1, 2}, {3, 4}) == 7); // 3+4
    // Cannot pick same row in adjacent columns: h1[0]=100, h2[1]=100 -> 200
    assert(maximumHappiness(2, {100, 1}, {1, 100}) == 200);
    // Must skip to avoid adjacent same-row
    assert(maximumHappiness(2, {100, 100}, {1, 1}) == 101);
    // Three columns, pick h1[0], h2[1], h1[2] not allowed because h1[0] and h1[2] not adjacent -> allowed
    assert(maximumHappiness(3, {100, 1, 100}, {1, 1, 1}) == 201);
    // All negative: choose max of each column (which is negative) or 0 by skipping all
    assert(maximumHappiness(1, {-5}, {-7}) == 0);
    // Single column: max of top, bottom, or skip
    assert(maximumHappiness(1, {10}, {5}) == 10);
    // All zeros
    assert(maximumHappiness(3, {0,0,0}, {0,0,0}) == 0);
    // Large values to test long long
    assert(maximumHappiness(2, {1000000000LL, 1000000000LL}, {1, 1}) == 1000000001LL);
    return 0;
}
